async function action(name){if(name==='close'){dialog.close();return;}if(name==='back-history'){view='history';render();return;}if(name==='new-native'){view='new';render();return;}if(name==='device'){dialog.close();root.PortalDeviceSettings.open('engine');return;}if(name==='refresh'){await refreshNative();await selectedNativeDetails();render();return;}if(name==='start-native'){await submitNative();return;}if(name==='native-files'){const value=await PortalNativeEngine.files('Files'),rows=value.entries||value.files||[];$('#native-task-file-list').textContent=rows.map(x=>typeof x==='string'?x:x.path||'Files/'+x.name).join('\n');return;}const row=tasks.get(selected);if(!row)return;if(name==='cancel')await cancel(row.id);if(name==='resume')await resume(row.id);if(name==='retry')await retry(row.id);if(name==='preview'){await preview(row.id);dialog.close();}if(name==='table')await showTable(row,0,100,{fixedSelectionId:null,fixedScopeLabel:null,selectedOnly:false});if(name==='matching-report'){dialog.close();await root.PortalSourceComparison.openReport(row.nativeId);}if(name==='matching-csv')await PortalNativeEngine.downloadMatches(row.nativeId,'csv');if(name==='matching-json')await PortalNativeEngine.downloadMatches(row.nativeId,'json');if(name==='metadata')await PortalNativeEngine.download(row.nativeId,'metadata');if(name==='download')await PortalNativeEngine.download(row.nativeId,'parquet');if(name==='folder'){dialog.close();await root.PortalDeviceSettings.openFolder(row.result.path.split('/').slice(0,-1),{workspaceId:row.workspaceId});}if(name==='layer'){const l=PortalLayers.layers.get(row.result.layerId);PortalLayers.selectLayer(l.id);PortalInventory.openTable(l.id,{scope:'loaded'});dialog.close();}}
